'use strict';
const STATIC_MODE=Boolean(globalThis.TALENT_ATLAS_STATIC);
const SNAPSHOT_CONFIG=globalThis.TALENT_ATLAS_STATIC||{};
const PATHS={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',cap:'m2 9 10-6 10 6-10 6-10-6M6 12v6c4 3 8 3 12 0v-6M22 9v7',book:'M4 19.5A2.5 2.5 0 0 1 6.5 17H20M6.5 3H20v19H6.5A2.5 2.5 0 0 1 4 19.5v-14A2.5 2.5 0 0 1 6.5 3',bookmark:'M5 3h14v18l-7-4-7 4V3',activity:'M3 12h4l3-8 4 16 3-8h4',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3M20 2v4M18 4h4',search:'m21 21-4.3-4.3M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',plus:'M12 5v14M5 12h14',download:'M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3',arrow:'M7 17 17 7M7 7h10v10',external:'M15 3h6v6M10 14 21 3M21 14v6H3V3h7',close:'m6 6 12 12M6 18 18 6',filter:'M4 7h16M7 12h10M10 17h4',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3m-4 9 3 3 5-6',check:'m5 12 4 4L19 6',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',help:'M9 8a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',menu:'M3 6h18M3 12h18M3 18h18',refresh:'M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',file:'M14 2H6v20h12V6l-4-4M14 2v5h5M8 12h8M8 16h5',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0'};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${PATHS[name]||PATHS.grid}"/></svg>`}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function url(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
const YEAR=new Date().getFullYear(),TARGET=YEAR+1;
const colors=[['#eef2f6','#52667e'],['#eaf0f7','#567393'],['#f1f3f5','#6b7280'],['#eaf2ef','#547866'],['#f5f1e9','#8b7656'],['#edf1f4','#617589']];
const DEFAULT={candidates:[],papers:[],saved:[],mode:'official',domain:'networking',role:'Network & Distributed Systems Researcher',keywords:'network, networking, congestion, routing, transport, datacenter',startYear:YEAR-2,endYear:YEAR,activities:[],coverage:null,profileQueue:[]};
let stored;
try { localStorage.removeItem('talent-atlas-v1'); stored=JSON.parse(localStorage.getItem('talent-atlas-v2')||'null'); } catch {}
if(stored?.version===2&&Array.isArray(stored.papers)&&Array.isArray(stored.candidates)){
 const papers=new Map(stored.papers.map(p=>[p.id,p]));
 stored.candidates=stored.candidates.filter(c=>!c.isSample&&!String(c.id).startsWith('sample-')).map(c=>({...c,papers:(c.paperIds||[]).map(id=>papers.get(id)).filter(Boolean)}));
}
const state={...DEFAULT,...(stored?.version===2?stored:{}),view:STATIC_MODE?'overview':document.getElementById('app')?.dataset?.defaultView||'overview',tab:'all',query:'',grad:'all',status:'all',conf:'all',sort:'fit',sortDir:'desc',minFit:0,page:1,pageSize:8,display:'table',selected:new Set(),busy:false,loading:!stored?.candidates?.length};
function normalizedWorkspace(){return {version:2,candidates:state.candidates.map(({papers,...c})=>({...c,paperIds:papers.map(p=>p.id)})),papers:state.papers,saved:state.saved,mode:'official',domain:state.domain,role:state.role,keywords:state.keywords,startYear:state.startYear,endYear:state.endYear,activities:state.activities,coverage:state.coverage,profileQueue:state.profileQueue||[]}}
function workspaceDatabase(){return new Promise((resolve,reject)=>{const request=indexedDB.open('talent-atlas-official',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('workspace'))request.result.createObjectStore('workspace')};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(new Error('Workspace cache is blocked.'))})}
async function readWorkspaceCache(){if(typeof indexedDB==='undefined')return null;const db=await workspaceDatabase();try{return await new Promise((resolve,reject)=>{const transaction=db.transaction('workspace','readonly'),request=transaction.objectStore('workspace').get('current');request.onsuccess=()=>resolve(request.result||null);request.onerror=()=>reject(request.error)})}finally{db.close()}}
async function writeWorkspaceCache(data){const db=await workspaceDatabase();try{await new Promise((resolve,reject)=>{const transaction=db.transaction('workspace','readwrite');transaction.objectStore('workspace').put(data,'current');transaction.oncomplete=()=>resolve();transaction.onerror=()=>reject(transaction.error);transaction.onabort=()=>reject(transaction.error)})}finally{db.close()}}
let persistenceQueue=Promise.resolve();
function persist(){
 const record=normalizedWorkspace();
 try{
  if(typeof indexedDB==='undefined'){localStorage.setItem('talent-atlas-v2',JSON.stringify(record));stored=record;return}
  const overrides=state.candidates.filter(c=>c.evidence||c.academicProfile).map(c=>({id:c.id,academicProfile:c.academicProfile,evidence:c.evidence,...(c.evidence?{affiliation:c.affiliation,affiliationLabel:c.affiliationLabel}:{}),status:c.status,degree:c.degree,startYear:c.startYear,durationMin:c.durationMin,durationMax:c.durationMax,gradYear:c.gradYear,gradRange:c.gradRange,expectedExplicit:c.expectedExplicit}));
  const preferences={version:2,dataInIndexedDB:true,saved:state.saved,domain:state.domain,role:state.role,keywords:state.keywords,startYear:state.startYear,endYear:state.endYear,activities:state.activities,overrides,profileQueue:state.profileQueue||[]};localStorage.setItem('talent-atlas-v2',JSON.stringify(preferences));stored=preferences;
  persistenceQueue=persistenceQueue.catch(()=>{}).then(()=>writeWorkspaceCache(record)).catch(()=>{toast('Your shortlist and evidence are saved. The full source cache could not be stored; it will reload from the server.')});
 }catch{toast('Browser storage is unavailable. Export your evidence and shortlist to keep a copy.')}
}
function applyOverrides(){for(const entry of stored?.overrides||[]){const c=state.candidates.find(c=>c.id===entry.id);if(c)Object.assign(c,entry)}}

function applyCollection(data,options={}){
 const previous=new Map(state.candidates.filter(c=>c.evidence||c.academicResearch||c.academicProfile).map(c=>[c.id,c]));
 state.papers=data.papers||[];const byId=new Map(state.papers.map(p=>[p.id,p]));
 state.candidates=(data.candidates||[]).map(c=>{const old=previous.get(c.id);const base={...c,papers:(c.paperIds||c.papers?.map(p=>p.id)||[]).map(id=>byId.get(id)).filter(Boolean)};if(!old)return base;const research={academicResearch:STATIC_MODE?(base.academicResearch||old.academicResearch):(old.academicResearch||base.academicResearch),academicProfile:old.academicProfile};if(!old.evidence&&!old.academicProfile)return {...base,...research};return {...base,...research,evidence:old.evidence,...(old.evidence?{affiliation:old.affiliation,affiliationLabel:old.affiliationLabel}:{}),status:old.status,degree:old.degree,startYear:old.startYear,durationMin:old.durationMin,durationMax:old.durationMax,gradYear:old.gradYear,gradRange:old.gradRange,expectedExplicit:old.expectedExplicit}});
 state.paperPage=1;state.paperQuery='';state.paperConference='';state.paperYear='';state.mode='official';state.coverage={...data.coverage,warnings:data.warnings||data.coverage?.warnings||[]};state.startYear=options.startYear||data.coverage?.startYear||state.startYear;state.endYear=options.endYear||data.coverage?.endYear||state.endYear;
 if(options.role)state.role=options.role;if(options.keywords)state.keywords=options.keywords;if(options.domain)state.domain=options.domain;
 applyOverrides();const ids=new Set(state.candidates.map(c=>c.id));state.saved=state.saved.filter(id=>ids.has(id));state.selected.clear();state.loading=false;persist();if(typeof profileResearchOnData==='function')profileResearchOnData();
}
async function loadBootstrap(){
 if(state.candidates.length&&!STATIC_MODE){state.loading=false;return}
 if(stored?.dataInIndexedDB&&!STATIC_MODE){try{const cached=await readWorkspaceCache();if(cached?.version===2&&cached.papers?.length&&cached.candidates?.length){state.profileQueue=stored?.profileQueue||cached.profileQueue||[];if(typeof normalizeProfileQueue==='function')normalizeProfileQueue();applyCollection({papers:cached.papers,candidates:cached.candidates,coverage:cached.coverage},stored);render();return}}catch{}}
 try{const response=await atlasFetch('/api/bootstrap');if(!response.ok)throw new Error('Official proceedings are not available yet.');const data=await response.json();applyCollection(data);render()}
 catch(error){state.loading=false;render();toast(error.message)}
}

function refreshProfileSelectionControls(){const toolbar=document.querySelector('.pr-toolbar');if(toolbar&&typeof profileResearchToolbar==='function')toolbar.outerHTML=profileResearchToolbar()}
function displayAffiliation(c){return c.evidence?c.affiliation:c.academicProfile?.fields?.currentAffiliation?.value||c.affiliation}
function displayInterests(c){const interests=c.academicProfile?.fields?.researchInterests?.value;return Array.isArray(interests)?interests:c.interests||[]}
function academicStatusLabel(value){if(!value)return 'Unknown';if(/post.?doc/i.test(value))return 'Postdoctoral researcher';if(/professor|faculty/i.test(value))return 'Faculty';if(/ph\.?d|doctoral/i.test(value))return 'PhD student';if(/master/i.test(value))return 'Master’s student';return value}
function applyReviewedAcademicFields(id,fieldNames){
 const c=state.candidates.find(c=>c.id===id),research=c?.academicResearch;
 if(!c||!research||research.identity?.status!=='matched')return {ok:false,error:'Resolve identity against paper evidence before accepting academic facts.'};
 const allowed=['currentAffiliation','currentStatus','researchInterests','degree','programStartYear','expectedGraduationYear'];
 if(!Array.isArray(fieldNames)||!fieldNames.length||fieldNames.some(f=>!allowed.includes(f)))return {ok:false,error:'Select supported academic fields to review.'};
 const sourceById=new Map((research.sources||[]).map(source=>[source.id,source]));const fields={...(c.academicProfile?.fields||{})},sourcePool=new Map((c.academicProfile?.sources||[]).map(source=>[source.url,source]));
 for(const name of fieldNames){const claim=research.academic?.[name];const sources=(claim?.sourceIds||[]).map(id=>sourceById.get(id)).filter(Boolean);
  if(!claim||claim.value==null||claim.basis!=='source_stated'||!sources.length||sources.some(source=>!String(source.url).startsWith('https://')||url(source.url)==='#'))return {ok:false,error:'Each accepted academic fact needs an explicit source and a valid citation.'};
  if(['programStartYear','expectedGraduationYear'].includes(name)&&(!Number.isInteger(claim.value)||claim.value<1990||claim.value>YEAR+15))return {ok:false,error:'The cited academic year needs review.'};
  if(name==='researchInterests'&&!Array.isArray(claim.value))return {ok:false,error:'Research interests must be a cited list.'};
  fields[name]={...claim,sourceIds:sources.map(source=>source.url)};for(const source of sources)sourcePool.set(source.url,{...source,id:source.url});
 }
 c.academicProfile={fields,sources:[...sourcePool.values()],identity:research.identity,reviewed:true,acceptedAt:new Date().toISOString(),reviewOrigin:research.researchMethod||'model_web_research'};
 if(!c.evidence){
  c.status=academicStatusLabel(fields.currentStatus?.value)||c.status;
  c.degree=fields.degree?.value||null;c.startYear=fields.programStartYear?.value||null;
  const expected=fields.expectedGraduationYear?.value;
  if(Number.isInteger(expected)){c.gradYear=expected;c.gradRange=[expected,expected];c.expectedExplicit=true}
  else if(c.degree&&c.startYear&&/ph\.?d|doctoral|master/i.test(c.degree)){const phd=/ph\.?d|doctoral/i.test(c.degree);c.durationMin=phd?5:1;c.durationMax=phd?6:2;c.gradRange=[c.startYear+c.durationMin,c.startYear+c.durationMax];c.gradYear=c.gradRange[0];c.expectedExplicit=false}
  else{c.gradYear=null;c.gradRange=null;c.expectedExplicit=false}
 }
 const job=(state.profileQueue||[]).find(job=>job.candidateId===id);if(job){job.state='resolved';job.finishedAt=new Date().toISOString()}
 notifyActivity('Academic findings reviewed',`${c.name}: ${fieldNames.length} cited academic fields accepted.${c.evidence?' Recruiter-entered evidence was preserved.':''}`);
 return {ok:true,acceptedFields:fieldNames,manualPreserved:Boolean(c.evidence)}
}
function initials(c){return c.initials||c.name.split(/\s+/).slice(0,2).map(x=>x[0]).join('')}
function avatar(c,i=0){const color=colors[Math.abs(c.name.length+i)%colors.length];return `<span class="avatar" style="background:${color[0]};color:${color[1]}">${esc(initials(c))}</span>`}
function candidateConfs(c){return [...new Set((c.papers||[]).map(p=>p.conference))]}
function target(c){return c.gradRange?.length===2?c.gradRange[0]<=TARGET&&c.gradRange[1]>=TARGET:c.gradYear===TARGET}
function rangeText(c){if(c.gradRange?.length===2&&c.gradRange[0]!==c.gradRange[1])return c.gradRange.join('–');return c.gradYear?String(c.gradYear):'Unknown'}
function matchList(){let list=state.candidates.filter(c=>{const text=[c.name,c.affiliation,displayAffiliation(c),c.status,...displayInterests(c),...candidateConfs(c)].join(' ').toLowerCase();return (c.fit||0)>=state.minFit&&(!state.query||text.includes(state.query.toLowerCase()))&&(state.view!=='shortlist'||state.saved.includes(c.id))&&(state.grad==='all'||(state.grad==='unknown'?!c.gradYear:c.gradYear===+state.grad))&&(state.status==='all'||c.status===state.status)&&(state.conf==='all'||candidateConfs(c).includes(state.conf))&&(state.tab!=='next'||target(c))&&(state.tab!=='saved'||state.saved.includes(c.id))});return list.sort((a,b)=>{const value=state.sort==='name'?a.name.localeCompare(b.name):state.sort==='grad'?(a.gradYear||9999)-(b.gradYear||9999):(a.fit||0)-(b.fit||0);return state.sortDir==='desc'?-value:value})}
function notifyActivity(title,description){state.activities.unshift({title,description,time:new Date().toISOString()});state.activities=state.activities.slice(0,30);persist()}
let toastTimer;function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000)}
function navItem(view,label,ico,count){if(STATIC_MODE&&view==='mapping-run')return '';return `<button data-action="${view==='mapping-run'?'open-mapping-run':view==='source-plans'?'open-source-plans':view==='profile-research'?'open-profile-research':'nav'}" data-view="${view}" aria-label="${esc(label)}" title="${esc(label)}" class="${state.view===view?'active':''}" ${state.view===view?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${count!==undefined?`<span class="count">${count}</span>`:''}</button>`}
function render(){const labels={'mapping-run':'Talent mapping run','source-plans':'Source plans','profile-research':'Profile research',artifacts:'Research artifacts',overview:'Overview',directory:'Talent directory',papers:'Accepted papers',conferences:'Conference map',shortlist:'Shortlist',activity:'Agent activity',methodology:'Methodology'};document.getElementById('app').innerHTML=`<a class="skip-link" href="#main-content">Skip to content</a><div class="shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#" data-action="home" aria-label="Talent Atlas home"><div class="brand-mark"><span></span><span></span></div><span>talent atlas<span style="color:#52667e">.</span></span></a><div class="workspace"><span class="initial">R</span><span>${STATIC_MODE?'Published research':'Recruiting workspace'}</span>${icon('down')}</div><div class="nav-caption">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${navItem('mapping-run','Talent mapping run','spark')}${navItem('overview','Overview','grid')}${STATIC_MODE?navItem('artifacts','Research artifacts','download'):''}${navItem('directory','Talent directory','users')}${navItem('papers','Accepted papers','file')}${navItem('conferences','Conference map','book')}${navItem('shortlist','Shortlist','bookmark',state.saved.filter(id=>state.candidates.some(c=>c.id===id)).length)}</nav><div class="nav-separator"></div><div class="nav-caption">INTELLIGENCE</div><nav class="nav" aria-label="Research tools">${navItem('source-plans','Source plans','link')}${navItem('profile-research',STATIC_MODE?'Published findings':'Profile research','spark')}${navItem('activity','Agent activity','activity')}${navItem('methodology','Methodology','shield')}</nav><div class="sidebar-bottom"><div class="agent-box"><div class="spark">${icon('spark')}</div>${STATIC_MODE?`<strong>Research, ready to explore.</strong><p>Browse the published evidence and take the complete dataset with you.</p><button data-action="nav" data-view="artifacts">Download artifacts ${icon('arrow')}</button>`:`<strong>Ahead of the next wave.</strong><p>Find emerging research talent before their next chapter begins.</p><button data-action="open-mapping-run">Start a mapping run ${icon('arrow')}</button>`}</div><div class="account"><div class="avatar">HR</div><div><strong>Talent acquisition</strong><small>Campus recruiting team</small></div></div></div></aside><button class="nav-backdrop" id="nav-backdrop" data-action="close-menu" aria-label="Close navigation" hidden></button><main class="main" id="main-content" tabindex="-1"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="Toggle navigation" aria-expanded="false" aria-controls="sidebar">${icon('menu')}</button><span>Workspace</span>${icon('chevron')}<strong>${labels[state.view]}</strong></div><div class="top-actions"><label class="global-search">${icon('search')}<input id="global-search" aria-label="Search talent" placeholder="Search researchers…" value="${esc(state.query)}"><span class="key-hint">⌘ K</span></label><span class="divider-v"></span><button class="icon-button" data-action="activity" aria-label="View agent activity">${icon('bell')}</button><button class="icon-button" data-action="settings" aria-label="Agent connection settings">${icon('settings')}</button><span class="top-avatar">HR</span></div></header><div class="content">${STATIC_MODE?snapshotBanner():''}<div class="title-row"><div><div class="eyebrow">RESEARCH TALENT INTELLIGENCE</div><h1>${state.view==='artifacts'?'The research, ready to take with you.':state.view==='mapping-run'?'Your next discovery starts here.':state.view==='source-plans'?'Official sources. Verified extraction.':state.view==='profile-research'?'Follow the evidence. Know the researcher.':state.view==='overview'?'Research talent, in focus.':state.view==='directory'?'Your next great minds.':state.view==='papers'?'Every paper. Every source.':state.view==='shortlist'?'A little closer to your team.':state.view==='conferences'?'Follow the research. Find the talent.':state.view==='activity'?'Every step, accounted for.':'Evidence behind every insight.'}</h1><p class="subtitle">${state.view==='artifacts'?'Download the published data, complete workbook, and original research evidence.':state.view==='mapping-run'?'Turn a research direction into a source-backed map of emerging talent.':state.view==='source-plans'?'Reusable publisher adapters, agent-assisted discovery, and versioned validation.':state.view==='profile-research'?'University pages, labs, personal sites, and CVs. Cited facts for human review.':state.view==='overview'?'Discover emerging researchers. Understand their expertise. Build your next team.':state.view==='directory'?esc(state.role)+' · '+state.startYear+'–'+state.endYear+' publication window':state.view==='papers'?'Official accepted-paper metadata, with full author lists and publisher links.':state.view==='shortlist'?'A focused collection of researchers to explore with your hiring team.':state.view==='conferences'?'Leading computer science venues, mapped to the expertise you need.':state.view==='activity'?'Research runs, sourcing coverage, and changes in your browser workspace.':'A transparent approach to research alignment and graduation estimates.'}</p></div><div style="${STATIC_MODE&&state.view==='artifacts'?'display:none':''}" class="title-actions ${state.view==='mapping-run'&&(typeof MR_state==='undefined'||!MR_state.run)?'initial-mapping-actions':''}"><button class="btn" data-action="${state.view==='mapping-run'?'mr-excel':'export'}" ${state.view==='mapping-run'&&(typeof MR_state==='undefined'||!MR_state.result)?'disabled':''}>${icon('download')} Export ${state.view==='mapping-run'?'Excel':state.view==='papers'?'papers':'candidates'}</button>${STATIC_MODE?'':`<button class="btn primary" data-action="mr-new" ${typeof MR_state==='undefined'||MR_state.pumping||MR_state.busy?'disabled':''}>${icon('plus')} New mapping run</button>`}</div></div>${state.view==='artifacts'?snapshotArtifactsPage():state.view==='mapping-run'&&typeof mappingRunWorkspace==='function'?mappingRunWorkspace():state.view==='source-plans'&&typeof sourcePlanWorkspace==='function'?sourcePlanWorkspace():state.view==='profile-research'&&typeof profileResearchWorkspace==='function'?profileResearchWorkspace():['overview','directory','shortlist'].includes(state.view)?dashboard():state.view==='papers'?papersPage():state.view==='conferences'?conferencePage():state.view==='activity'?activityPage():methodPage()}<footer class="bottom-note"><span>${icon('shield')} Professional academic evidence. Human-reviewed decisions.</span><span>Talent Atlas · A clearer view of what’s next.</span></footer></div></main></div>`;if(['overview','directory','shortlist'].includes(state.view))renderResults();}
function dashboard(){return `<div class="scope-row"><div class="scope-tabs" role="tablist" aria-label="Candidate scope"><button role="tab" aria-selected="${state.tab==='all'}" data-action="tab" data-tab="all" class="${state.tab==='all'?'active':''}">All talent</button><button role="tab" aria-selected="${state.tab==='next'}" data-action="tab" data-tab="next" class="${state.tab==='next'?'active':''}">${TARGET} graduates</button><button role="tab" aria-selected="${state.tab==='saved'}" data-action="tab" data-tab="saved" class="${state.tab==='saved'?'active':''}">Shortlisted</button></div><button class="sample-badge live" data-action="workspace-info"><span class="dot"></span>${STATIC_MODE?'Published snapshot':'Official proceedings'} ${icon('down')}</button></div>${state.coverage?coverageNote():''}${state.view==='overview'?`<div class="metrics">${metric('Author records',state.candidates.length,'users',`${state.startYear}–${state.endYear} publication window`)}${metric('Potential next-year graduates',state.candidates.filter(target).length,'cap',state.candidates.some(c=>c.gradYear)?`Potential ${TARGET} graduates · estimates`:'Academic timeline evidence not yet collected','next')}${metric('Research-aligned profiles',state.candidates.filter(c=>c.fit>=85).length,'target',`Keyword alignment ≥85 · review required`,'fit')}${metric('Conference papers',uniquePapers(),'book',`${new Set(state.candidates.flatMap(candidateConfs)).size} conferences in this workspace`)}</div><div class="chart-grid"><section class="panel"><div class="panel-header"><div><h2>Talent landscape</h2><p>All author records · grouped by alignment and paper count</p></div><button class="btn" data-action="reset-map">${icon('filter')} All researchers</button></div><div class="chart-wrap" id="landscape"></div><div class="legend"><span class="legend-item"><i class="legend-dot" style="background:#527599"></i>Publisher-listed author groups</span><span class="legend-item">Size = record count</span><span class="chart-note">Select a group to explore</span></div></section><section class="panel"><div class="panel-header"><div><h2>Graduation outlook</h2><p>Your future campus hiring pipeline</p></div><span class="tag">${TARGET} hiring</span></div><div class="pipeline-wrap" id="pipeline"></div><div class="pipeline-note">${icon('spark')}<span>${state.candidates.some(c=>c.gradYear)?'Graduation years are estimates unless a profile source states them explicitly.':'Publication records do not establish graduation dates. Add current academic profile evidence to build this pipeline.'}</span></div></section></div>`:''}<section class="panel table-panel"><div class="table-top"><div><h2 class="table-title">${state.view==='shortlist'?'Your shortlist':'Explore research talent'} <span class="number-pill" id="result-count">${state.candidates.length}</span></h2><p>${state.loading?'Loading verified official proceedings…':'Publisher-listed authors · publication affiliation · current status requires profile evidence'}</p></div><div style="display:flex;gap:7px;flex-wrap:wrap">${typeof profileResearchToolbar==='function'?profileResearchToolbar():''}<button class="btn" data-action="export-selected">${icon('download')} Export selection</button></div></div><div class="filters"><label class="table-search">${icon('search')}<input id="candidate-search" aria-label="Search name, university, or expertise" placeholder="Search name, university, expertise..." value="${esc(state.query)}"></label><select id="grad-filter" aria-label="Graduation year"><option value="all">Graduation year</option>${[...new Set([YEAR,YEAR+1,YEAR+2,YEAR+3,YEAR+4,...state.candidates.map(c=>c.gradYear).filter(Boolean)])].sort((a,b)=>a-b).map(y=>`<option value="${y}" ${state.grad===String(y)?'selected':''}>${y}${y===TARGET?' · Next year':''}</option>`).join('')}<option value="unknown" ${state.grad==='unknown'?'selected':''}>Unknown</option></select><select id="status-filter" aria-label="Academic status"><option value="all">Academic status</option>${[...new Set(state.candidates.map(c=>c.status))].sort().map(s=>`<option ${state.status===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="conf-filter" aria-label="Conference"><option value="all">Conference</option>${[...new Set(state.candidates.flatMap(candidateConfs))].sort().map(s=>`<option ${state.conf===s?'selected':''}>${esc(s)}</option>`).join('')}</select><button class="reset" data-action="reset-filters">Reset</button><span class="filter-spacer"></span><div class="view-switch" aria-label="View type"><button data-action="display" data-display="table" class="${state.display==='table'?'active':''}" aria-label="Table view">${icon('list')}</button><button data-action="display" data-display="cards" class="${state.display==='cards'?'active':''}" aria-label="Card view">${icon('grid')}</button></div></div><div id="results"></div></section>${!STATIC_MODE&&state.view!=='shortlist'?`<div class="ai-strip">${icon('spark')}<div><h3>Great research. Even better possibilities.</h3><p>Describe your hiring needs and map the conferences where your future team publishes.</p></div><button class="btn ghost" data-action="new-search">Build a talent map ${icon('arrow')}</button></div>`:''}`}
function metric(label,value,ico,foot,action){return `<div class="metric"><div class="metric-head"><span class="metric-icon">${icon(ico)}</span>${label}</div><div class="metric-value">${value.toLocaleString()}</div><div class="metric-foot">${foot}</div>${action?`<button class="metric-button" data-action="metric" data-metric="${action}" aria-label="Explore ${label.toLowerCase()}"></button>`:''}</div>`}
function uniquePapers(){return state.papers.length}
function coverageNote(){const v=state.coverage;return `<div class="coverage"><strong>${v.collectionComplete?'Complete edition indexes':v.partial?'Coverage limits reported':'Official source collection'} · ${state.startYear}–${state.endYear}</strong> · ${esc(v.completenessLabel||v.note||v.description||'Results reflect the returned search scope, not every accepted paper.')} <button class="btn ghost" data-action="coverage" style="padding:2px 5px">View source coverage ${icon('arrow')}</button></div>`}
function renderResults(){const list=matchList(),pages=Math.max(1,Math.ceil(list.length/state.pageSize));state.page=Math.min(state.page,pages);const start=(state.page-1)*state.pageSize,rows=list.slice(start,start+state.pageSize);document.getElementById('result-count').textContent=list.length;document.getElementById('results').innerHTML=list.length?(state.display==='table'?table(rows):cards(rows))+`<div class="table-footer"><span>Showing ${start+1}–${Math.min(start+state.pageSize,list.length)} of ${list.length} researchers</span><div class="pagination"><button data-action="page" data-page="${Math.max(1,state.page-1)}" aria-label="Previous page">‹</button>${Array.from({length:Math.min(pages,5)},(_,i)=>{const p=pages<=5?i+1:Math.min(Math.max(1,state.page-2),pages-4)+i;return `<button data-action="page" data-page="${p}" class="${p===state.page?'active':''}" aria-label="Page ${p}">${p}</button>`}).join('')}<button data-action="page" data-page="${Math.min(pages,state.page+1)}" aria-label="Next page">›</button></div></div>`:`<div class="empty">${icon('search')}<h3>No researchers in this view</h3><p>${state.view==='shortlist'?'Save a profile with the bookmark icon to start building your shortlist.':state.tab==='next'?'Current graduation evidence has not identified this cohort. Paper metadata alone does not establish availability. Add academic profile evidence to assess graduation timing.':'Try a broader search, reset your filters, or collect papers for a different conference.'}</p><button class="btn" data-action="reset-filters">Reset filters</button> ${STATIC_MODE?'':`<button class="btn primary" data-action="new-search">New talent search</button>`}</div>`;if(state.view==='overview'){renderMap(list);renderPipeline(list)}}
function tags(c,max=2){return displayInterests(c).slice(0,max).map((s,i)=>`<span class="tag ${i%2?'blue':''}">${esc(s)}</span>`).join('')||'<span class="subtext">Not yet researched</span>'}
function bookmark(c){return `<button class="bookmark ${state.saved.includes(c.id)?'saved':''}" data-action="bookmark" data-id="${esc(c.id)}" aria-label="${state.saved.includes(c.id)?'Remove from':'Add to'} shortlist: ${esc(c.name)}" aria-pressed="${state.saved.includes(c.id)}">${icon('bookmark')}</button>`}
function fit(c){return `<span class="fit"><span class="fit-bar"><i style="width:${Math.max(0,Math.min(100,c.fit||0))}%"></i></span>${c.fit||0}%</span>`}
function table(rows){return `<div class="table-scroll"><table class="candidate-table"><thead><tr><th><input type="checkbox" class="check" id="select-page" aria-label="Select this page" ${rows.every(c=>state.selected.has(c.id))?'checked':''}></th><th><button class="text-sort" data-action="sort" data-sort="name">Researcher ↕</button></th><th>ACADEMIC STATUS</th><th>RESEARCH EXPERTISE</th><th><button class="text-sort" data-action="sort" data-sort="grad">EST. GRADUATION ↕</button></th><th>PUBLICATIONS</th><th><button class="text-sort" data-action="sort" data-sort="fit">RESEARCH FIT ↓</button></th><th></th></tr></thead><tbody>${rows.map((c,i)=>`<tr><td><input type="checkbox" class="check row-check" data-id="${esc(c.id)}" aria-label="Select ${esc(c.name)}" ${state.selected.has(c.id)?'checked':''}></td><td><div class="candidate-ident">${avatar(c,i)}<div><button class="name-btn" data-action="profile" data-id="${esc(c.id)}">${esc(c.name)}</button><div class="subtext">${esc(displayAffiliation(c)||'Affiliation not yet verified')}</div></div></div></td><td><span class="status">${esc(c.status||'Unknown')}</span></td><td><div class="tags">${tags(c)}</div></td><td><span class="grad">${c.gradYear?c.gradYear:'Unknown'}${target(c)?'<span class="next">NEXT YEAR</span>':''}</span><div class="subtext" style="margin-top:5px">${c.gradYear?`<i class="confidence-dot low"></i>${c.expectedExplicit?'Source stated':`Range: ${rangeText(c)}`}`:'Needs profile evidence'}</div></td><td><span style="color:#64748b">${c.papers?.length||0} papers</span><div class="subtext" style="margin-top:5px">${esc(candidateConfs(c).slice(0,2).join(' · '))}</div></td><td>${fit(c)}</td><td>${bookmark(c)}</td></tr>`).join('')}</tbody></table></div>`}
function cards(rows){return `<div class="cards-grid">${rows.map((c,i)=>`<article class="candidate-card"><header>${avatar(c,i)}<div><button class="name-btn" data-action="profile" data-id="${esc(c.id)}">${esc(c.name)}</button><span class="subtext">${esc(displayAffiliation(c)||'Affiliation unverified')}</span></div>${bookmark(c)}</header><span class="status">${esc(c.status)}</span><div class="tags">${tags(c)}</div><footer><span class="grad">${rangeText(c)} ${c.gradYear?'est.':''}</span>${fit(c)}</footer></article>`).join('')}</div>`}
function renderMap(list){
 const el=document.getElementById('landscape');if(!el)return;const w=580,h=208,left=45,right=18,top=14,bottom=41,pw=w-left-right,ph=h-top-bottom;
 const groups=new Map();for(const c of list){const bucket=Math.floor((c.fit||0)/10)*10,count=Math.min(8,c.papers.length),key=bucket+':'+count;let group=groups.get(key);if(!group){group={bucket,count,ids:[]};groups.set(key,group)}group.ids.push(c.id)}
 el.innerHTML=`<svg class="scatter" viewBox="0 0 ${w} ${h}" role="group" aria-label="All researchers aggregated by alignment score and paper count. Select a group to inspect its candidate records.">${[0,2,4,6,8].map(n=>{const y=top+ph-ph*n/8;return `<line x1="${left}" x2="${w-right}" y1="${y}" y2="${y}" class="grid"/><text x="${left-13}" y="${y+3}" text-anchor="end">${n===8?'8+':n}</text>`}).join('')}${[0,25,50,75,100].map(n=>`<text x="${left+pw*n/100}" y="${h-24}" text-anchor="middle">${n}</text>`).join('')}<text class="axis-title" x="${w/2}" y="${h-6}" text-anchor="middle">Research alignment score →</text><text class="axis-title" transform="translate(12 91) rotate(-90)" text-anchor="middle">Collected papers</text><rect x="${left+pw*.85}" y="${top}" width="${pw*.15}" height="${ph}" fill="#eef3f8" opacity=".7"/>${[...groups.values()].map(g=>`<g><circle class="bubble" data-action="map-group" data-bucket="${g.bucket}" data-count="${g.count}" role="button" tabindex="0" aria-label="${g.ids.length} author records, ${g.bucket} to ${Math.min(100,g.bucket+9)} percent alignment, ${g.count}${g.count===8?'+':''} papers" cx="${left+pw*Math.min(100,g.bucket+4)/100}" cy="${top+ph-ph*g.count/8}" r="${Math.min(19,5+Math.sqrt(g.ids.length)*.8)}" fill="#527599" fill-opacity=".78"><title>${g.ids.length} author records · ${g.bucket}–${Math.min(100,g.bucket+9)}% alignment · ${g.count}${g.count===8?'+':''} papers</title></circle>${g.ids.length>=10?`<text x="${left+pw*Math.min(100,g.bucket+4)/100}" y="${top+ph-ph*g.count/8+3}" text-anchor="middle" style="font-size:8px;fill:#fff;pointer-events:none">${g.ids.length}</text>`:''}</g>`).join('')}</svg>`
}
function mapGroup(bucket,count){const list=matchList().filter(c=>Math.floor((c.fit||0)/10)*10===bucket&&Math.min(8,c.papers.length)===count);modal(`${list.length} author records in this group.`,`${bucket}–${Math.min(100,bucket+9)}% research alignment · ${count}${count===8?'+':''} collected papers`,`<div class="cluster-list">${list.slice(0,60).map(c=>`<button class="cluster-person" data-action="profile" data-id="${esc(c.id)}">${avatar(c)}<span><strong>${esc(c.name)}</strong><small>${esc(c.affiliation||'Affiliation not provided')}</small></span>${icon('chevron')}</button>`).join('')}</div>${list.length>60?`<p class="evidence-line">Showing the first 60 records in this group. All ${list.length} remain in the talent directory and exports.</p>`:''}`,`<small>Circle sizes reflect actual record counts.</small><button class="btn primary" data-action="close">Done</button>`)}

function renderPipeline(list){const el=document.getElementById('pipeline');if(!el)return;const years=[...new Set([YEAR,TARGET,YEAR+2,YEAR+3,...list.map(c=>c.gradYear).filter(Boolean)])].sort((a,b)=>a-b).concat('Unknown'),counts=years.map(y=>list.filter(c=>y==='Unknown'?!c.gradYear:c.gradYear===y).length),max=Math.max(1,...counts);el.innerHTML=`<div class="pipeline-chart">${years.map((y,i)=>`<div class="bar-group ${y===TARGET?'target':''}"><span class="bar-value">${counts[i]}</span><button class="bar" style="height:${Math.max(3,counts[i]/max*118)}px" data-action="year" data-year="${y==='Unknown'?'unknown':y}" aria-label="Show ${y} graduation profiles: ${counts[i]}"></button><span class="bar-label">${y}</span></div>`).join('')}</div>`}
function domainOptions(value,all=false){return (all?'<option value="all">All CS domains</option>':'')+DOMAINS.map(d=>`<option value="${d.id}" ${value===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}
function paperMatches(){return state.papers.filter(p=>(!state.paperQuery||[p.title,p.rawByline,p.section,p.conference,...(p.authors||[]).map(a=>a.name)].join(' ').toLowerCase().includes(state.paperQuery.toLowerCase()))&&(!state.paperConference||p.conferenceId===state.paperConference)&&(!state.paperYear||p.year===+state.paperYear)).sort((a,b)=>b.year-a.year||a.title.localeCompare(b.title))}
function papersPage(){const list=paperMatches();const pages=Math.max(1,Math.ceil(list.length/20)),page=Math.min(state.paperPage||1,pages),start=(page-1)*20,rows=list.slice(start,start+20);state.paperPage=page;return `<div class="section-content">${state.coverage?coverageNote():''}<section class="panel"><div class="table-top"><div><h2 class="table-title">Accepted paper library <span class="number-pill">${list.length}</span></h2><p>All collected records retained · publisher author lists · no search-result cap</p></div><button class="btn" data-action="export-source">${icon('download')} Source JSON</button></div><div class="filters"><label class="table-search" style="width:300px">${icon('search')}<input id="paper-search" value="${esc(state.paperQuery||'')}" placeholder="Search papers, authors, or topics..." aria-label="Search accepted papers"></label><select id="paper-conference" aria-label="Filter paper conference"><option value="">All conferences</option>${[...new Map(state.papers.map(p=>[p.conferenceId,p.conference])).entries()].map(([id,name])=>`<option value="${id}" ${state.paperConference===id?'selected':''}>${esc(name)}</option>`).join('')}</select><select id="paper-year" aria-label="Filter paper year"><option value="">All years</option>${[...new Set(state.papers.map(p=>p.year))].sort((a,b)=>b-a).map(y=>`<option ${+state.paperYear===y?'selected':''}>${y}</option>`).join('')}</select><button class="reset" data-action="reset-papers">Reset</button></div><div class="table-scroll"><table class="candidate-table paper-table"><thead><tr><th></th><th>PAPER AND OFFICIAL SOURCE</th><th>CONFERENCE</th><th>AUTHOR OCCURRENCES</th><th>METADATA</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${icon('file')}</td><td class="paper-title-cell"><button class="name-btn" data-action="paper" data-id="${esc(p.id)}">${esc(p.title)}</button><div class="subtext">${esc(p.section||'Official accepted paper')}</div></td><td><span class="tag">${esc(p.conference)} ${p.year}</span></td><td>${p.authors?.length||0}<div class="subtext">${esc((p.authors||[]).slice(0,2).map(a=>a.name).join(', '))}${p.authors?.length>2?' +'+(p.authors.length-2):''}</div></td><td><span class="status">${p.detailVerified?'Citation metadata':'Publisher listing'}</span></td><td><a class="icon-button" href="${url(p.url)}" target="_blank" rel="noopener" aria-label="Open official paper source">${icon('external')}</a></td></tr>`).join('')}</tbody></table></div>${list.length?`<div class="table-footer"><span>${start+1}–${Math.min(start+20,list.length)} of ${list.length} papers</span><div class="pagination"><button data-action="paper-page" data-page="${Math.max(1,page-1)}">Previous</button><span>${page} / ${pages}</span><button data-action="paper-page" data-page="${Math.min(pages,page+1)}">Next</button></div></div>`:'<div class="empty"><h3>No papers in this view</h3><p>Change your filters or collect official conference editions.</p></div>'}</section></div>`}
function paperModal(id){const p=state.papers.find(x=>x.id===id);if(!p)return;modal(esc(p.title),`${esc(p.conference)} ${p.year} · ${esc(p.section||'Accepted paper')}`,`<div class="paper-detail-meta"><span class="tag green">Official publisher record</span><span class="tag">${p.detailVerified?'Structured citation metadata':'Accepted-paper listing'}</span></div><div class="drawer-section"><h3>Authors and publication-time affiliations</h3>${(p.authors||[]).map(a=>`<div class="paper-author"><strong>${esc(a.name)}</strong><span>${esc(a.affiliations?.join('; ')||'Affiliation not provided by this source')}</span></div>`).join('')}</div>${p.rawByline?`<details class="raw-byline"><summary>Original publisher author line</summary><p>${esc(p.rawByline)}</p></details>`:''}${p.abstractSnippet?`<div class="drawer-section"><h3>Publisher abstract excerpt</h3><p>${esc(p.abstractSnippet)}</p></div>`:''}<div class="info-box" style="margin-top:20px">${icon('shield')}<span>These institutions are associated with the paper’s publication. Current employment, degree status, and graduation are not established by this record.</span></div>`,`<a class="btn" href="${url(p.url)}" target="_blank" rel="noopener">Official paper ${icon('external')}</a>${p.pdfUrl?`<a class="btn primary" href="${url(p.pdfUrl)}" target="_blank" rel="noopener">Read paper PDF ${icon('external')}</a>`:'<button class="btn primary" data-action="close">Done</button>'}`)}
function downloadFile(content,type,name){const blob=new Blob([content],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportSource(){downloadFile(JSON.stringify({schemaVersion:2,papers:state.papers,coverage:state.coverage},null,2),'application/json',`talent-atlas-official-${state.startYear}-${state.endYear}.json`);toast(`${state.papers.length} official paper records exported with provenance.`)}
function exportPapers(){const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,m=>"'"+m).replace(/"/g,'""')+'"';const rows=[['Paper title','Conference','Year','Authors and publication affiliations','Publisher author line','Official URL','PDF URL','Metadata status','Edition source'],...paperMatches().map(p=>[p.title,p.conference,p.year,(p.authors||[]).map(a=>a.name+' ('+(a.affiliations?.join('; ')||'affiliation not provided')+')').join('; '),p.rawByline,p.url,p.pdfUrl||'',p.detailVerified?'Citation metadata':'Official listing',p.sourceUrl])];downloadFile('\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8;',`accepted-papers-${state.startYear}-${state.endYear}.csv`);toast(`${rows.length-1} accepted paper records exported.`)}
function conferencePage(){
 const domain=state.catalogDomain||state.domain||'networking',key=state.keywords.toLowerCase();const venues=CONFERENCES.filter(c=>domain==='all'||c.domains.includes(domain));
 return `<div class="scope-row"><label class="domain-picker">${icon('grid')}<select id="catalog-domain" aria-label="Computer science domain">${domainOptions(domain,true)}</select></label><span class="source-summary">${DOMAINS.length} CS domains · ${CONFERENCES.length} curated venues</span></div><div class="coverage"><strong>Domain-led sourcing.</strong> Each venue links to its official publisher. Connected adapters collect entire edition indexes; mapped venues without an adapter are clearly marked.</div><div class="conference-grid">${venues.sort((a,b)=>relevance(b,key)-relevance(a,key)).map(c=>`<article class="conference-card"><div class="conf-logo" style="background:#eef2f6;color:#52667e">${esc(c.name)}</div><h3>${esc(c.name)}</h3><p>${esc(c.full)}</p><div class="tags"><span class="tag">${esc(c.area)}</span><span class="tag ${c.connectorStatus==='ready'?'green':''}">${c.connectorStatus==='ready'?'Official-source connector':'Official source mapped'}</span></div>${(c.note||c.lifecycleNote||c.scheduleNote)?`<p class="conf-note">${esc([c.note,c.lifecycleNote,c.scheduleNote].filter(Boolean).join(' '))}</p>`:''}<div class="conf-foot"><span>${c.schedule==='biennial'?'Biennial':'Annual'} · ${esc(c.id==='atc'?'USENIX / SIGOPS':c.provider)}</span><a href="${url(c.url)}" target="_blank" rel="noopener noreferrer">Official source ${icon('external')}</a></div>${STATIC_MODE?'':conferenceSourceReady(c)?`<button class="btn" style="margin-top:17px;width:100%" data-action="search-conference" data-conf="${c.id}">Collect this conference ${icon('arrow')}</button>`:`<button class="btn" style="margin-top:17px;width:100%" data-action="open-source-plans">Resolve official source ${icon('arrow')}</button>`}</article>`).join('')}</div>`
}
function relevance(c,key){const words=' '+key.toLowerCase().replace(/[^a-z0-9]+/g,' ')+' ';return c.topics.filter(t=>words.includes(' '+t.toLowerCase().replace(/[^a-z0-9]+/g,' ')+' ')).length}
function activityPage(){if(STATIC_MODE&&!state.activities.length)return `<section class="panel section-content empty">${icon('activity')}<h3>Your local research trail</h3><p>Shortlisting and evidence reviews you make here appear in this browser’s activity trail. Published research files are available in Research artifacts.</p><button class="btn" data-action="nav" data-view="artifacts">Browse artifacts</button></section>`;return `<section class="panel section-content">${state.activities.length?state.activities.map(a=>`<article class="activity-item"><span class="activity-dot"></span><div><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p></div><time datetime="${esc(a.time)}">${new Date(a.time).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</time></article>`).join(''):`<div class="empty">${icon('activity')}<h3>Your research trail starts here.</h3><p>Run a search, import conference papers, or add profile evidence to create a transparent activity trail.</p><button class="btn primary" data-action="new-search">Start a talent search</button></div>`}</section>`}
function methodPage(){if(STATIC_MODE)return snapshotMethodPage();return `<div class="article section-content"><h2>Official proceedings are the starting point</h2><p>This workspace contains real papers and author names retrieved from official conference sources. There are no illustrative candidate profiles or generated papers. A curated catalog maps computer science domains to established venues. Networking includes SIGCOMM, NSDI, CoNEXT, and IMC; operating and distributed systems include OSDI, SOSP, EuroSys, and ATC.</p><h2>Complete editions, with measurable coverage</h2><p>Collection starts from the publisher’s full accepted-paper or technical-session index for each selected year. It does not stop at a search-result limit or candidate count. USENIX individual pages supply structured citation titles, author names, publication-time institutions, and PDF links. Coverage reports the listing count, checked detail pages, missing metadata, excluded non-paper sessions, and source retrieval date. A complete index does not imply every author’s current profile has been researched.</p><h2>Author records and identity</h2><p>Records with exactly matching publisher name and publication affiliation are tentatively grouped. Name-only records stay scoped to their paper. This reduces accidental merges but can split the same researcher across institutions. Every underlying author occurrence remains available in Accepted papers. Identity, present affiliation, degree status, and graduation still require current profile evidence.</p><h2>Graduation estimates</h2><table><thead><tr><th>Evidence</th><th>Result</th></tr></thead><tbody><tr><td>Explicit expected graduation year from a current profile</td><td>Source-stated year, pending recruiter review</td></tr><tr><td>Degree and start year with a source</td><td>Range from an editable program-duration assumption</td></tr><tr><td>Only a paper or a publication affiliation</td><td>Unknown</td></tr></tbody></table><p>Initial planning assumptions are 5–6 years for a PhD and 1–2 years for a master’s degree; recruiters should use the relevant program’s actual guidance. A range overlapping ${TARGET} appears in the next-year cohort. The earlier endpoint is used in the histogram. No graduation date is inferred from first publication, seniority, or a person’s name.</p><h2>Research alignment</h2><p>Scores show the fraction of supplied research phrases found in paper titles and session topics. They measure sourcing relevance, not overall suitability or predicted job performance. Every profile lists the matched terms. Institution prestige and personal traits do not affect the score.</p><h2>Data storage and refresh</h2><p>Source plans are keyed by conference, year, and main track. Known publisher adapters run deterministically. Agents propose declarative extraction plans when a source is missing or its parser fails; validation checks official authority, edition, track, records, pagination, and counts before activation. Plans and checks are versioned in shared server storage. Failed refreshes keep a dated successful snapshot available. The app includes a dated snapshot of official source metadata so the dashboard opens with real results. A new search can refresh complete publisher indexes, reusing checked detail metadata for unchanged papers and flagging new detail pages for further collection. Shortlists and recruiter evidence are saved in this browser. Paper and candidate exports include provenance. Profile agents can search university and lab pages, personal academic sites, CVs, and public professional pages once a server model is configured. Each claim carries citations, source dates, and confidence. Identity ambiguity stays unresolved. Proposed facts need review before entering filters or graduation counts; manual evidence takes precedence. No ethnicity, nationality, or other protected attributes are classified or used for screening.</p><p><a href="https://www.usenix.org/conference/osdi25/technical-sessions" target="_blank" rel="noopener">OSDI official proceedings</a> · <a href="https://www.usenix.org/conference/nsdi25/technical-sessions" target="_blank" rel="noopener">NSDI official proceedings</a> · <a href="https://conferences.sigcomm.org/" target="_blank" rel="noopener">ACM SIGCOMM conferences</a> · <a href="https://csrankings.org/" target="_blank" rel="noopener">CS domain and venue reference</a></p></div>`}
let previousFocus=null;
function modal(title,subtitle,body,foot=''){previousFocus=document.activeElement;document.getElementById('overlay-root').innerHTML=`<div class="modal-backdrop" data-dismiss="modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="icon-button overlay-close" data-action="close" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${body}</div>${foot?`<footer class="modal-foot">${foot}</footer>`:''}</section></div>`;setTimeout(()=>document.querySelector('.modal input,.modal button')?.focus(),30)}
function closeOverlay(){if(state.busy)return;document.getElementById('overlay-root').innerHTML='';previousFocus?.focus?.()}
function conferenceSourceReady(c){return c.connectorStatus==='ready'||(typeof SP_state!=='undefined'&&SP_state.plans.some(row=>row.status==='active'&&row.plan?.conferenceId===c.id))}
function scopeOptions(domain,selected=[]){
 return CONFERENCES.filter(c=>c.domains.includes(domain)).map(c=>`<label class="conf-option ${!conferenceSourceReady(c)?'unconnected':''}"><input type="checkbox" name="conferences" value="${c.id}" ${selected.includes(c.id)&&conferenceSourceReady(c)?'checked':''} ${!conferenceSourceReady(c)?'disabled':''}><span>${esc(c.name)}<small>${c.connectorStatus==='ready'?'Official source connected':'Source mapped · adapter pending'}</small></span></label>`).join('')
}
function searchModal(oneConf){
 const conf=CONFERENCES.find(c=>c.id===oneConf),domain=conf?.domains?.[0]||state.domain||'networking';const selected=oneConf?[oneConf]:CONFERENCES.filter(c=>c.domains[0]===domain&&conferenceSourceReady(c)).map(c=>c.id);
 modal('Follow the domain. Collect the evidence.','Full accepted-paper indexes from official conference sources.',`<form id="research-form"><div class="field"><label for="domain">Computer science domain</label><select id="domain" name="domain">${domainOptions(domain)}</select></div><div class="field"><label for="role">Hiring role</label><input id="role" name="role" required maxlength="180" value="${esc(state.role)}" placeholder="e.g. Network Systems Researcher"></div><div class="field"><label for="keywords">Research expertise</label><textarea id="keywords" name="keywords" required maxlength="500">${esc(state.keywords)}</textarea><small>Comma-separated phrases explain research alignment. They do not restrict which accepted papers are collected.</small></div><div class="field"><label>Conferences in this domain</label><div class="conference-options" id="conference-options">${scopeOptions(domain,selected)}</div><small id="recommendation-note">Connected sources collect every listed paper in the selected editions.</small></div><div class="field"><label for="window">Publication window</label><select id="window" name="window"><option value="${YEAR-2},${YEAR}" ${state.startYear===YEAR-2?'selected':''}>${YEAR-2}–${YEAR} · latest three calendar years</option><option value="${YEAR-3},${YEAR-1}" ${state.startYear===YEAR-3?'selected':''}>${YEAR-3}–${YEAR-1} · previous three complete years</option></select></div><label class="checkbox-label"><input type="checkbox" name="refresh" id="refresh-sources" checked> Refresh official publisher indexes</label><div class="info-box">${icon('shield')}<span>All accepted-paper metadata is retained; no candidate-count cap. Checked source metadata is reused where available. Missing details and unavailable editions are reported. Current academic status stays unknown until a profile supports it.</span></div><div id="research-error" class="error-text" role="alert"></div></form>`,`<small>Only official source data enters this workspace.</small><button class="btn primary" data-action="run-research">${icon('refresh')} Collect accepted papers</button>`)
}
function researchOptions(){const form=document.getElementById('research-form');if(!form.reportValidity())return null;const data=new FormData(form),conferences=data.getAll('conferences');if(!conferences.length||conferences.length>8){document.getElementById('research-error').textContent='Choose between 1 and 8 connected conferences in this domain.';return null}const [startYear,endYear]=data.get('window').split(',').map(Number);return {role:data.get('role').trim(),keywords:data.get('keywords').trim(),domain:data.get('domain'),conferences,startYear,endYear,refresh:data.get('refresh')==='on'}}
async function runResearch(){
 const options=researchOptions();if(!options)return;state.busy=true;const body=document.querySelector('.modal-body'),foot=document.querySelector('.modal-foot');
 body.innerHTML=`<div class="loading-inline"><span class="spinner"></span>Collecting official accepted-paper indexes…</div><ul class="progress-list"><li><span class="step-num">1</span>${options.conferences.length} conferences · ${options.startYear}–${options.endYear}</li><li><span class="step-num">2</span>Read every listed accepted paper, with no result cap</li><li><span class="step-num">3</span>Link publisher author and affiliation evidence</li><li><span class="step-num">4</span>Report coverage and leave unsupported facts unknown</li></ul><div class="info-box">${icon('clock')}<span>Official pages can be unavailable or revised. Each edition reports what was collected and when. Existing recruiter evidence is retained for matching records.</span></div>`;foot.innerHTML='<small>Keep this window open while publisher indexes are checked.</small>';
 try{
 const response=await atlasFetch('/api/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(options),signal:AbortSignal.timeout(150000)}),data=await response.json();if(!response.ok)throw new Error(data.error||'The source request could not be completed.');
 if(!data.papers?.length){state.busy=false;modal('No published papers returned.','Your current workspace has been kept.',`<div class="info-box amber">${icon('help')}<span>${esc(data.warnings?.join(' ')||'The official source did not return accepted papers for these editions.')}</span></div>`,`<button class="btn" data-action="close">Keep workspace</button><button class="btn primary" data-action="new-search">Adjust scope</button>`);return}
 applyCollection(data,options);resetFilters(false);state.view='overview';notifyActivity('Official proceedings collected',`${state.papers.length} accepted papers · ${state.candidates.length} author records · ${options.startYear}–${options.endYear}. ${data.coverage?.partial?'Source gaps are listed in coverage.':'Full listed editions collected.'}`);state.busy=false;closeOverlay();render();toast(`${state.papers.length} real papers collected. Review the source coverage.`)
 }catch(error){state.busy=false;modal('The publisher request needs another try.','Your current workspace has been kept.',`<div class="info-box amber">${icon('help')}<span>${esc(error.name==='TimeoutError'?'The source timed out. Retry with cached official metadata by turning off refresh.':error.message)}</span></div>`,`<button class="btn" data-action="close">Keep workspace</button><button class="btn primary" data-action="new-search">Try again</button>`)}
}
function profile(id){const c=state.candidates.find(x=>x.id===id);if(!c)return;previousFocus=document.activeElement;document.getElementById('overlay-root').innerHTML=`<div class="drawer-backdrop" data-dismiss="drawer"><aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="profile-title"><div class="drawer-top"><span>RESEARCHER PROFILE</span><button class="icon-button" data-action="close" aria-label="Close profile">${icon('close')}</button></div><div class="drawer-profile">${avatar(c)}<div><h2 id="profile-title">${esc(c.name)}</h2><p>${esc(displayAffiliation(c)||'Current affiliation not yet verified')}</p></div></div><div class="drawer-badges"><span class="status">${esc(c.status||'Unknown')}</span><span class="tag">${c.evidence?'Recruiter-supplied evidence':'Publisher metadata · identity review needed'}</span></div>${c.affiliation?`<div class="info-box">${icon('book')}<span>${esc(c.affiliationLabel||'Publication-time affiliation from the official proceedings. This does not establish current academic status.')} ${esc(c.identityNote||'')}</span></div>`:''}<div class="drawer-stat-grid"><div class="drawer-stat"><strong>${c.fit||0}%</strong><span>Research alignment</span></div><div class="drawer-stat"><strong>${rangeText(c)}</strong><span>${c.expectedExplicit?'Source-stated graduation':'Estimated graduation'}</span></div><div class="drawer-stat"><strong>${c.papers?.length||0}</strong><span>Collected papers</span></div></div><div class="drawer-actions"><button class="btn ${state.saved.includes(c.id)?'':'primary'}" data-action="bookmark-profile" data-id="${esc(c.id)}">${icon('bookmark')} ${state.saved.includes(c.id)?'Shortlisted':'Add to shortlist'}</button>${c.profileUrl?`<a class="btn" href="${url(c.profileUrl)}" target="_blank" rel="noopener noreferrer">Source record ${icon('external')}</a>`:''}</div>${typeof profileResearchSection==='function'?profileResearchSection(c):''}<section class="drawer-section"><h3>Research expertise</h3><div class="tags">${tags(c,10)}</div><p>${esc(c.interestsLabel||'Topics reflect collected paper titles and metadata; review papers for depth and current interests.')}</p></section><section class="drawer-section"><h3>Why this profile aligns</h3><p>${esc(c.fitReason||'Alignment is based on keyword matches across collected papers. It does not measure overall job suitability.')}</p><span class="tag">Role: ${esc(state.role)}</span></section><section class="drawer-section"><h3>Graduation evidence</h3>${c.gradYear?`<p class="evidence-line">${c.expectedExplicit?`Expected year <b>${c.gradYear}</b>, entered from a profile source. Recruiter review is still required.`:`${esc(c.degree||'Degree')} start: <b>${c.startYear||'Unknown'}</b> · ${c.durationMin|| (c.degree==='PhD'?5:1)}–${c.durationMax||(c.degree==='PhD'?6:2)} year planning assumption.<br>Estimated range: <b>${rangeText(c)}</b>. The earlier year is used in pipeline counts. This is not confirmed availability.`}</p>`:'<p>No degree program or start-year evidence is available. Publication dates alone do not establish graduation timing.</p>'}${c.evidence?`<a class="source-link" href="${url(c.evidence.sourceUrl)}" target="_blank" rel="noopener noreferrer">${icon('link')} Recruiter-supplied profile source ${icon('external')}</a><p class="subtext">Added ${new Date(c.evidence.addedAt).toLocaleDateString()} · not automatically verified</p>`:''}<button class="btn" data-action="evidence" data-id="${esc(c.id)}">${icon('plus')} Add academic evidence</button></section><section class="drawer-section"><h3>Selected publications</h3>${(c.papers||[]).slice(0,8).map(p=>`<article class="paper">${p.url?`<a href="${url(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.title)} ${icon('external')}</a>`:`<strong>${esc(p.title)}</strong>`}<small>${esc(p.conference)} · ${p.year}</small></article>`).join('')}</section><section class="drawer-section"><h3>Source trail</h3>${c.sources?.length?c.sources.map(s=>`<a class="source-link" href="${url(s.url)}" target="_blank" rel="noopener noreferrer">${icon('link')}${esc(s.label)} ${icon('external')}</a>`).join(''):`<p>No additional profile source is attached yet.</p>`}</section></aside></div>`;document.querySelector('.drawer .icon-button')?.focus()}
function evidenceModal(id){const c=state.candidates.find(x=>x.id===id);if(!c)return;modal('Add the academic context.',`Evidence for ${esc(c.name)} · recruiter review is required`, `<form id="evidence-form" data-id="${esc(id)}"><div class="field"><label for="e-affiliation">Current academic affiliation</label><input id="e-affiliation" name="affiliation" maxlength="200" value="${esc(c.affiliation||'')}" placeholder="University or research institution"></div><div class="field-row"><div class="field"><label for="e-status">Academic status</label><select id="e-status" name="status">${['Unknown','PhD student','Master’s student','Researcher','Graduated'].map(s=>`<option ${c.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label for="e-start">Program start year</label><input id="e-start" name="startYear" type="number" min="1990" max="${YEAR}" value="${c.startYear||''}" placeholder="Unknown"></div></div><div class="field-row"><div class="field"><label for="e-expected">Explicit expected graduation year</label><input id="e-expected" name="expected" type="number" min="${YEAR}" max="${YEAR+15}" value="${c.expectedExplicit?c.gradYear:''}" placeholder="Only if stated in the source"></div><div class="field"><label for="e-duration">Program duration assumption</label><select id="e-duration" name="duration">${[[5,6,'PhD'],[3,4,'PhD'],[4,5,'PhD'],[1,2,'Master’s'],[2,2,'Master’s'],[2,3,'Master’s']].map(([a,b,d])=>`<option value="${a},${b}" ${((c.durationMin|| (c.degree==='Master’s'?1:5))===a&&(c.durationMax|| (c.degree==='Master’s'?2:6))===b)?'selected':''}>${d} · ${a===b?a:a+'–'+b} years</option>`).join('')}</select></div></div><div class="field"><label for="e-source">Academic profile or program source URL</label><input type="url" id="e-source" name="sourceUrl" required value="${esc(c.evidence?.sourceUrl||'')}" placeholder="https://university.edu/researcher"><small>Use an institutional page, personal academic page, or CV. Add a source that supports the entered facts and timeline.</small></div><div class="info-box">${icon('shield')}<span>Entered facts remain labeled recruiter-supplied. The app does not automatically read or verify this link. Unknown degree or start year means no estimated range.</span></div><div class="error-text" id="e-error" role="alert"></div></form>`,`<button class="btn" data-action="profile" data-id="${esc(id)}">Back to profile</button><button class="btn primary" data-action="save-evidence">Save evidence</button>`)}
function saveEvidence(){
 const form=document.getElementById('evidence-form');if(!form.reportValidity())return;
 const d=new FormData(form),c=state.candidates.find(x=>x.id===form.dataset.id),u=url(d.get('sourceUrl'));
 if(u==='#'){document.getElementById('e-error').textContent='Use an http or https source URL.';return}
 const status=d.get('status'),degree=status==='PhD student'?'PhD':status==='Master’s student'?'Master’s':null;
 const expected=d.get('expected')?Number(d.get('expected')):null,startYear=d.get('startYear')?Number(d.get('startYear')):null;
 const [min,max]=d.get('duration').split(',').map(Number);
 if(!expected&&degree&&((degree==='PhD'&&max<=3)||(degree==='Master’s'&&min>=3))){document.getElementById('e-error').textContent='Choose a program duration that matches the selected degree.';return}
 c.affiliation=d.get('affiliation').trim()||c.affiliation;c.affiliationLabel='Recruiter-supplied current affiliation; source link not automatically verified.';
 c.status=status;c.degree=degree;c.startYear=startYear;c.expectedExplicit=Boolean(expected);c.durationMin=min;c.durationMax=max;
 if(expected){c.gradYear=expected;c.gradRange=[expected,expected]}else if(degree&&startYear){c.gradRange=[startYear+min,startYear+max];c.gradYear=c.gradRange[0]}else{c.gradYear=null;c.gradRange=null}
 c.evidence={sourceUrl:u,addedAt:new Date().toISOString()};c.confidence=expected?'Source-stated · review needed':c.gradYear?'Assumption-based range':'Unknown';
 notifyActivity('Academic evidence added',`${c.name}: ${c.gradYear?'graduation '+rangeText(c):'graduation remains unknown'}. Recruiter-supplied source.`);
 render();profile(c.id);toast('Academic evidence saved in this browser.')
}
async function settings(){if(STATIC_MODE){modal('About this published snapshot.','Research results you can browse and download.',`<div class="snapshot-about"><p>This website contains a published copy of research data. New collection and AI research run separately; publishing updated results refreshes this snapshot.</p><p>Your shortlist, reviewed fields, and manually entered evidence stay in this browser. Export them to retain or share your work.</p><p>Published ${esc(snapshotDate(SNAPSHOT_CONFIG.publishedAt))}. Original source retrieval dates remain attached to the records.</p></div>`,`<button class="btn primary" data-action="close">Done</button>`);return}modal('Your research connections.','Public-source collection is ready. AI enrichment needs a model connection.',`<div id="connection-status" class="loading-inline"><span class="spinner"></span>Checking source configuration…</div>`,`<small>Private app · browser-local recruiting workspace</small><button class="btn primary" data-action="close">Done</button>`);try{const res=await atlasFetch('/api/status'),d=await res.json();const statusEl=document.getElementById('connection-status');if(!statusEl)return;statusEl.innerHTML=`<div style="width:100%"><div class="activity-item" style="padding:12px 0"><span class="activity-dot" style="background:#9ec0ac"></span><div><h3>Official USENIX proceedings</h3><p>Complete edition indexes for OSDI, NSDI, FAST, and USENIX Security. Author affiliations are linked to paper metadata, not inferred current employment.</p></div></div><div class="activity-item" style="padding:16px 0"><span class="activity-dot" style="background:#bdab8f"></span><div><h3>Academic profile agents · ${d.aiConfigured?'server configuration present':'live connection required'}</h3><p>Review the cited public-source pilot now. New model runs require OpenAI Developers setup and server configuration; provider access is checked when a live request runs.</p><button class="btn ghost" data-action="open-profile-research">Open profile research ${icon('arrow')}</button></div></div><div class="activity-item" style="padding:16px 0"><span class="activity-dot" style="background:#94a3b8"></span><div><h3>Workspace persistence</h3><p>Results, evidence, and saved profiles are stored in this browser. Export CSV to share or retain a copy.</p></div></div><div class="info-box" style="margin-top:18px">${icon('shield')}<span>Never paste API keys into a candidate field or source import. Runtime credentials are configured securely on the server.</span></div></div>`}catch{const statusEl=document.getElementById('connection-status');if(statusEl)statusEl.innerHTML='<p>Connection status is unavailable. Try again when the app server is reachable.</p>'}}
function coverageModal(){const v=state.coverage;if(!v){toast('Official source metadata is still loading.');return}modal('Every edition, accounted for.','Official publisher listings · all accepted-paper records retained.',`<div class="info-box">${icon('book')}<span>${esc(v.completenessLabel||'Source coverage is recorded separately for each edition.')} ${v.retrievedAt?'Snapshot retrieved '+esc(new Date(v.retrievedAt).toLocaleString()):''}</span></div>${(v.editions||[]).map(e=>`<div class="activity-item" style="padding:13px 0"><span class="activity-dot"></span><div><h3>${esc(e.conference)} · ${e.year} <span class="tag ${e.partial?'':'green'}">${esc(e.status||'collected')}</span></h3><p>${e.listingPapers??e.mainTrackRecords??0} listed papers${e.expectedPapers?' / '+e.expectedPapers+' stated by publisher':''} · ${e.detailVerified??0} citation records checked${e.detailUnavailable?' · '+e.detailUnavailable+' details unavailable':''}${e.detailCitationMetadataMissing?' · '+e.detailCitationMetadataMissing+' without citation tags':''}</p><p>${esc(e.completeness||e.note||'')} ${e.authorsWithoutAffiliation?'· '+e.authorsWithoutAffiliation+' author occurrences without affiliation':''}</p><a href="${url(e.sourceUrl)}" target="_blank" rel="noopener" style="font-size:10px">Open official edition ${icon('external')}</a></div></div>`).join('')}${v.warnings?.length?`<div class="notice">${v.warnings.map(esc).join('<br>')}</div>`:''}`,`<button class="btn" data-action="export-source">${icon('download')} Export source metadata</button><button class="btn primary" data-action="close">Done</button>`)}
function resetFilters(redraw=true){state.query='';state.grad='all';state.status='all';state.conf='all';state.tab='all';state.minFit=0;state.page=1;if(redraw)render()}
function exportCSV(selectedOnly=false){const list=selectedOnly?state.candidates.filter(c=>state.selected.has(c.id)):matchList();if(!list.length){toast(selectedOnly?'Select at least one candidate to export.':'No candidates match this view.');return}const columns=['Name','Latest affiliation','Academic status','Research interests','Estimated graduation year','Graduation range','Graduation basis','Research fit (%)','Fit explanation','Collected paper count','Conferences','Shortlisted','Profile URL','Evidence URL','Source URLs','Data type','Academic research state','Accepted academic sources','Academic research checked at'];const rows=list.map(c=>[c.name,displayAffiliation(c)||'Unknown',c.status,displayInterests(c).join('; '),c.gradYear||'Unknown',rangeText(c),c.expectedExplicit?(c.evidence?'Recruiter-supplied source-stated year':'Reviewed source-stated academic year'):c.gradYear?'Estimate from program duration assumption':'Insufficient evidence',c.fit,c.fitReason,c.papers.length,candidateConfs(c).join('; '),state.saved.includes(c.id)?'Yes':'No',c.profileUrl||'',c.evidence?.sourceUrl||'',(c.sources||[]).map(s=>s.url).join('; '),'Official proceedings; profile review required',c.academicProfile?'Reviewed':c.academicResearch?'Needs review':'Not researched',(c.academicProfile?.sources||[]).map(s=>s.url).join('; '),c.academicResearch?.queriedAt||'']);const cell=v=>{let t=String(v??'');if(/^[=+@\-\t\r]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'};const blob=new Blob(['\uFEFF'+[columns,...rows].map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`talent-atlas-${state.mode}-${TARGET}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast(`${list.length} profiles exported.`)}
function toggleNavigation(open){
 const sidebar=document.getElementById('sidebar'),trigger=document.querySelector('[data-action="menu"]'),backdrop=document.getElementById('nav-backdrop');
 if(!sidebar)return;const expanded=open??!sidebar.classList.contains('mobile-open');
 sidebar.classList.toggle('mobile-open',expanded);const main=document.getElementById('main-content');if(main)main.inert=expanded;trigger?.setAttribute('aria-expanded',String(expanded));if(backdrop)backdrop.hidden=!expanded;
 if(expanded)sidebar.querySelector('button')?.focus();else if(document.activeElement&&sidebar.contains(document.activeElement))trigger?.focus();
}
document.addEventListener('click',event=>{const targetEl=event.target.closest('[data-action]');if(!targetEl){if(event.target.matches('[data-dismiss]'))closeOverlay();return}event.preventDefault();const action=targetEl.dataset.action,id=targetEl.dataset.id;
 if(STATIC_MODE&&['new-search','search-conference','run-research','apply-conferences','open-mapping-run','mr-new'].includes(action)){toast('New research runs separately. Updated results appear when a new snapshot is published.');return}
 if(action==='close')closeOverlay();
 else if(action==='nav'||action==='home'||action==='activity'){state.view=action==='nav'?targetEl.dataset.view:action==='home'?'overview':'activity';resetFilters(false);render();if(['overview','directory','shortlist'].includes(state.view)&&!state.candidates.length)loadBootstrap();window.scrollTo(0,0)}
 else if(action==='menu')toggleNavigation();
 else if(action==='close-menu')toggleNavigation(false);
 else if(action==='new-search')searchModal();
 else if(action==='search-conference')searchModal(targetEl.dataset.conf);
 else if(action==='apply-conferences'){const key=document.getElementById('keywords').value.toLowerCase();const suggested=[...CONFERENCES].sort((a,b)=>relevance(b,key)-relevance(a,key)).slice(0,3).filter(c=>relevance(c,key)>0).map(c=>c.id);if(!suggested.length){document.getElementById('recommendation-note').textContent='Add a research area such as machine learning, language, vision, systems, or software engineering.';}else{document.querySelectorAll('input[name=conferences]').forEach(el=>el.checked=suggested.includes(el.value));document.getElementById('recommendation-note').textContent='Selected: '+suggested.map(id=>CONFERENCES.find(c=>c.id===id).name).join(', ')+'.'}}
 else if(action==='run-research')runResearch();
 else if(action==='profile')profile(id);
 else if(action==='evidence')evidenceModal(id);
 else if(action==='save-evidence')saveEvidence();
 else if(action==='tab'){state.tab=targetEl.dataset.tab;state.page=1;render()}
 else if(action==='metric'){if(targetEl.dataset.metric==='next'){state.tab='next';state.page=1;render()}else{state.query='';state.sort='fit';state.sortDir='desc';state.minFit=85;state.page=1;render();document.querySelector('.table-panel')?.scrollIntoView({behavior:'smooth',block:'start'});toast('Showing profiles with research alignment of at least 85%.')}}
 else if(action==='year'){state.grad=targetEl.dataset.year;state.page=1;render()}
 else if(action==='page'){state.page=+targetEl.dataset.page;renderResults()}
 else if(action==='display'){state.display=targetEl.dataset.display;render()}
 else if(action==='sort'){state.sortDir=state.sort===targetEl.dataset.sort?(state.sortDir==='asc'?'desc':'asc'):(targetEl.dataset.sort==='fit'?'desc':'asc');state.sort=targetEl.dataset.sort;state.page=1;renderResults()}
 else if(action==='reset-filters'||action==='reset-map')resetFilters();
 else if(action==='bookmark'||action==='bookmark-profile'){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();if(action==='bookmark-profile'){render();profile(id)}else render();toast(state.saved.includes(id)?'Added to your shortlist.':'Removed from your shortlist.')}
 else if(action==='export'){if(state.view==='papers')exportPapers();else exportCSV();}
 else if(action==='export-selected')exportCSV(true);
 else if(action==='settings')settings();
 else if(action==='coverage')coverageModal();
 else if(action==='export-source')exportSource();
 else if(action==='paper')paperModal(id);
 else if(action==='map-group')mapGroup(+targetEl.dataset.bucket,+targetEl.dataset.count);
 else if(action==='paper-page'){state.paperPage=+targetEl.dataset.page;render()}
 else if(action==='reset-papers'){state.paperPage=1;state.paperQuery='';state.paperConference='';state.paperYear='';render()}
 else if(action==='workspace-info')coverageModal();

});
document.addEventListener('input',event=>{if(event.target.id==='paper-search'){state.paperQuery=event.target.value;state.paperPage=1;const pos=event.target.selectionStart;render();const field=document.getElementById('paper-search');field?.focus();field?.setSelectionRange(pos,pos)}if(['candidate-search','global-search'].includes(event.target.id)){state.query=event.target.value;state.page=1;if(!['overview','directory','shortlist'].includes(state.view)){state.view='directory';render();document.getElementById('candidate-search')?.focus()}else{const other=document.getElementById(event.target.id==='candidate-search'?'global-search':'candidate-search');if(other)other.value=state.query;renderResults()}}if(event.target.id==='keywords'){const note=document.getElementById('recommendation-note');if(note)note.textContent='Expertise affects alignment scores; every accepted paper in the selected editions is retained.';}});
document.addEventListener('change',async event=>{const el=event.target;if(el.id==='catalog-domain'){state.catalogDomain=el.value;render()}if(el.id==='domain'){const ready=CONFERENCES.filter(c=>c.domains[0]===el.value&&conferenceSourceReady(c)).map(c=>c.id);document.getElementById('conference-options').innerHTML=scopeOptions(el.value,ready)}if(el.id==='paper-conference'||el.id==='paper-year'){state[el.id==='paper-conference'?'paperConference':'paperYear']=el.value;state.paperPage=1;render()}if(['grad-filter','status-filter','conf-filter'].includes(el.id)){state[el.id==='grad-filter'?'grad':el.id==='status-filter'?'status':'conf']=el.value;state.page=1;renderResults()}if(el.classList.contains('row-check')){if(el.checked)state.selected.add(el.dataset.id);else state.selected.delete(el.dataset.id);refreshProfileSelectionControls()}if(el.id==='select-page'){const list=matchList().slice((state.page-1)*state.pageSize,state.page*state.pageSize);list.forEach(c=>el.checked?state.selected.add(c.id):state.selected.delete(c.id));renderResults();refreshProfileSelectionControls()}if(el.id==='e-status'){const duration=document.getElementById('e-duration');if(el.value==='Master’s student')duration.value='1,2';else if(el.value==='PhD student')duration.value='5,6'}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='evidence-form')saveEvidence();else if(e.target.id==='research-form')runResearch()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeOverlay();toggleNavigation(false)}if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();document.getElementById('global-search')?.focus()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('circle[data-action]')){e.preventDefault();if(e.target.dataset.action==='map-group')mapGroup(+e.target.dataset.bucket,+e.target.dataset.count);else profile(e.target.dataset.id)}if(e.key==='Tab'&&document.querySelector('[aria-modal="true"]')){const modalEl=document.querySelector('[aria-modal="true"]'),focusables=[...modalEl.querySelectorAll('button:not(:disabled),input:not([hidden]),select,textarea,a[href]')].filter(el=>el.offsetParent!==null);if(!focusables.length)return;const first=focusables[0],last=focusables[focusables.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
if(typeof window.matchMedia==='function')window.matchMedia('(max-width: 720px)').addEventListener('change',event=>{if(!event.matches)toggleNavigation(false)});
render();
if(state.view!=='mapping-run')loadBootstrap();

function snapshotDate(value){const date=new Date(value);return value&&!Number.isNaN(date.getTime())?date.toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'}):'Date not recorded'}
function snapshotBanner(){return `<aside class="snapshot-banner" aria-label="Published snapshot"><span class="snapshot-banner-icon">${icon('book')}</span><div><strong>Published research snapshot</strong><p>Published ${esc(snapshotDate(SNAPSHOT_CONFIG.publishedAt))} · Browse the evidence and download the complete artifacts. Shortlists and evidence edits are saved in this browser.</p></div><button class="btn ghost" data-action="nav" data-view="artifacts">Research artifacts ${icon('arrow')}</button></aside>`}
function snapshotArtifactHref(value){try{const href=new URL(value,document.baseURI);return href.origin===new URL(document.baseURI).origin&&['http:','https:'].includes(href.protocol)?href.href:'#'}catch{return '#'}}
function snapshotArtifactsPage(){
 const artifacts=(SNAPSHOT_CONFIG.artifacts||[]).filter(artifact=>snapshotArtifactHref(artifact.href)!=='#');
 return `<div class="section-content"><div class="snapshot-artifacts-intro"><span class="snapshot-kicker">PUBLISHED COLLECTION</span><h2>Evidence you can work with.</h2><p>These files contain the published research collection. Source dates, citations, coverage gaps, and unreviewed proposals stay attached to the evidence.</p></div><div class="snapshot-artifact-grid">${artifacts.map(artifact=>{const size=Number(artifact.bytes),sizeLabel=Number.isFinite(size)&&size>0?(size>=1048576?(size/1048576).toFixed(1)+' MB':Math.ceil(size/1024)+' KB'):'';return `<article class="panel snapshot-artifact-card"><span class="snapshot-file-icon">${icon(String(artifact.type).toUpperCase()==='XLSX'?'grid':'file')}</span><span class="snapshot-kicker">${esc(artifact.type||'Research artifact')}${sizeLabel?' · '+sizeLabel:''}</span><h3>${esc(artifact.title||artifact.filename||'Research artifact')}</h3><p>${esc(artifact.description||'Published research data with its original evidence trail.')}</p><a class="btn" href="${esc(snapshotArtifactHref(artifact.href))}" download="${esc(artifact.filename||'')}">${icon('download')} Download ${esc(artifact.type||'file')}</a></article>`}).join('')}</div>${artifacts.length?'':'<section class="panel empty"><h3>No downloadable artifacts were included.</h3><p>You can still export the visible papers and author records from this dashboard.</p></section>'}<div class="snapshot-artifacts-note">${icon('clock')}<div><strong>New research becomes a new publication.</strong><p>Run research in the research workspace, export the results, and push the updated data to GitHub. The website republishes automatically after that push. Your browser’s local shortlist and evidence edits are separate from these published files.</p></div></div></div>`;
}

function snapshotMethodPage(){return `<div class="article section-content"><h2>Official proceedings are the starting point</h2><p>This published snapshot contains real paper records and publisher-listed author names from official conference sources. Every retained paper links to its source. Coverage gaps, missing citation metadata, and differences between publisher-stated counts and parsed records remain visible in source coverage.</p><h2>Publication records and academic identity</h2><p>Publication-time affiliations do not establish a researcher’s current affiliation, enrollment, employment, or availability. Exact publisher names and affiliations form provisional author groups; name-only records stay scoped to their papers. Source-backed academic proposals remain separate from publication metadata and require identity review.</p><h2>Research alignment and graduation</h2><p>Research alignment reflects keyword matches in paper titles and publication topics. It is a sourcing aid, not a measure of job performance. Graduation dates remain unknown unless supported by academic evidence. Explicit source-stated dates and estimates from degree start years are labeled separately; duration assumptions remain visible.</p><h2>Published findings and local review</h2><p>The published academic evidence includes citations, source dates, identity status, and confidence. A publication date for this website does not make the underlying evidence newly researched. Review the original sources before accepting fields. Your shortlist, accepted academic fields, and manually entered evidence are stored in this browser. They do not change the published collection or other visitors’ workspaces.</p><h2>Refreshing the publication</h2><p>New research and source collection run separately from this static website. Exported results and artifacts are published through GitHub after an update is pushed. Research artifacts contains the complete downloadable snapshot and workbook. No live model requests start from this website.</p><p><a href="https://www.usenix.org/conferences" target="_blank" rel="noopener noreferrer">USENIX official proceedings</a> · <a href="https://conferences.sigcomm.org/" target="_blank" rel="noopener noreferrer">ACM SIGCOMM conferences</a></p></div>`}
